contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call sequence: possibly transfer some tokens to caller, then attempt burn by caller,
    // and finally assert that if caller is not owner then totalSupply did not decrease.
    // We observe pre- and post- totalSupply and compare.
    function run(address recipient, uint256 amount) public {
        // Preconditions to make the test meaningful:
        // ensure recipient has at least `amount` by having owner mint to recipient if needed.
        // We cannot call owned-only functions directly here, but owner is the deployer of C.
        // So require that recipient is not the owner to distinguish behavior.
        require(recipient != address(c));

        // Record totalSupply before any actions
        uint256 before = c.totalSupply();

        // Ensure recipient has tokens to burn: ask owner to transfer/mint to recipient by calling mintToken.
        // The test harness (verifier) can choose parameters so that the owner (c.owner()) is address(this)
        // or some other account; we cannot force owner to act here. To keep minimal calls, we instead
        // try to transfer from owner to recipient by invoking c.transfer, which will only succeed if
        // this contract is the owner (has tokens). So to keep the test general and check the distinguishing
        // behavior, we first attempt a transfer from this contract; if it fails the require will revert and
        // the verifier will explore inputs where it succeeds (i.e., this contract has tokens).

        // Attempt to transfer tokens from msg.sender of this test to recipient so recipient can burn.
        // The call is to c.transfer which transfers tokens from this test's address (msg.sender in C is this contract)
        // to recipient. The test caller must ensure this contract has tokens; that's a precondition the verifier can satisfy.
        c.transfer(recipient, amount);

        // Let recipient burn their tokens by calling burn via the c contract. Since burn uses msg.sender inside C,
        // we must call burn from this contract to represent 'this' burning. But we need to model a non-owner caller
        // causing totalSupply decrease if mutant allows it. To do that, we perform a burn call from this contract
        // (which is not owner of C when the verifier arranges it) through c.burn.
        // However, we cannot impersonate `recipient` address to call c.burn as recipient. Instead we let this contract
        // hold the tokens and burn them directly: we transferred tokens to recipient above, but we need this contract
        // to be the burner. So instead, we should transfer to this contract before burning. Adjust sequence:
    }

    // Because the single public function must hold ALL logic, provide a corrected combined function.
    function runTest(address other, uint256 amt) public {
        require(other != address(c));

        uint256 before = c.totalSupply();

        // Transfer amt tokens from this contract to `other`, then transfer them back so `other` holds them briefly.
        // Minimal calls: transfer to other, then other cannot call (we can't), so instead keep tokens in this contract.
        // Simpler approach: assume this contract holds tokens to begin with; transfer none. Then burn from this contract.
        // To make verifier find a distinguishing trace, we require that this contract is not the owner.
        require(c.owner() != address(this));

        // Now attempt to burn amt from this contract's balance via c.burn
        c.burn(amt);

        uint256 after = c.totalSupply();

        // The distinguishing rule: if the caller is not the owner, totalSupply must NOT decrease.
        // In original P this holds because onlyOwner prevents non-owner from calling burn; the call would revert
        // and after == before. In mutant M, non-owner can burn their tokens, reducing totalSupply, violating this.
        assert(!(c.owner() != address(this)) || after == before);
    }

    // Provide empty receive/fallback to accept ethers if needed by tests (optional)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address burner, uint256 amount) public payable {
        // precondition: burner has at least `amount` tokens so burn will succeed if allowed
        require(c.balanceOf(burner) >= amount);
        uint256 before = c.totalSupply();
        // call burn from this contract by making this contract act as burner via delegatecall is not allowed,
        // so we require that this test contract is the burner: ensure burner == address(this)
        // instead, we will check the general property by only calling burn from this contract
        // and requiring this contract not to be the owner for the case that should be forbidden in mutant.
        // Ensure that this contract is not the owner to make the distinction meaningful
        require(address(this) != c.owner());
        // transfer tokens to this contract if needed so it can attempt to burn
        // Note: transfer only possible if original token holder (owner) sent tokens; but we observe balance precondition
        // We assume the test contract already has tokens (enforced by precondition by using its own balance)
        require(c.balanceOf(address(this)) >= amount);

        // boundary: the difference is observable after this call
        c.burn(amount);

        uint256 after = c.totalSupply();
        // General rule: if caller is not owner, totalSupply must not decrease due to burn
        assert(after >= before);
    }
    receive() external payable { }
}

